rows = {}
for f in sorted(glob.glob('tools/i18n/src/tr*.txt')):
    for r in open(f, encoding='utf8').read().split('\n'):
        if r.strip(): c = r.split('|'); rows[int(c[0])] = c[1:]
out = []
have = set(keys)
for k, v in T.items():
    assert len(v) == 9, k
    if k in have: continue
    keys.append(k); have.add(k); out.append('|'.join([str(len(keys) - 1)] + v))
for n, (a, b, langs) in REPL.items():
    nk = keys[n].replace(a, b)
    if nk in have: continue
    old = rows[n]; new = []
    for (x, y), t in zip(langs, old):
        assert x in t, (n, x); new.append(t.replace(x, y))
    keys.append(nk); have.add(nk); out.append('|'.join([str(len(keys) - 1)] + new))
json.dump(keys, open(KJ, 'w', encoding='utf8'), ensure_ascii=False, indent=0)
with open('tools/i18n/src/tr13.txt', 'a', encoding='utf8') as o:
    for r in out: o.write(r + '\n')
print('added', len(out))
